package events

// Publisher writes match events as JSON to the match-events topic.
func (p *Publisher) Publish(ctx context.Context, e Event) error {
	b, _ := json.Marshal(e)
	return p.cl.ProduceSync(ctx, &kgo.Record{Topic: "match-events", Value: b}).FirstErr()
}

package scoring

// Apply adds the points in e to the player's row in the leaderboard table.
func Apply(ctx context.Context, db *pgxpool.Pool, e events.Event) error {
	_, err := db.Exec(ctx, "UPDATE leaderboard SET points = points + $1 WHERE player_id = $2", e.Points, e.PlayerID)
	return err
}

package main

// main starts the match server: it opens the Postgres pool, creates a franz-go client
// with kgo.SeedBrokers(os.Getenv("KAFKA_BROKERS")), and for each event calls
// publisher.Publish and then scoring.Apply.
